// An authored three-dimensional alpine horizon; original survey data remains a source reference.
function swissMountains(){const g=createHorizonGeometry(height);const pos=g.attributes.position,colors=[],surfaces=[];for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),y=height(x,z);pos.setY(i,y);const c=alpineLandscapeColor(x,z,y,height);colors.push(c.r,c.g,c.b);const w=alpineSurfaceWeights(x,z,y,height);surfaces.push(w.rock,w.snow);}g.setAttribute('alpineSurface',new T.Float32BufferAttribute(surfaces,2));g.setAttribute('color',new T.Float32BufferAttribute(colors,3));g.computeVertexNormals();const horizonMaterial=mountainMaterial(groundMaterial.map,limestoneMap);const mountain=add(g,horizonMaterial,scene);mountain.castShadow=false;mountain.receiveShadow=false;mountain.userData.kind='authored-alpine-horizon';scene.userData.relief={samples:relief.size**2,min:Math.min(...relief.elevation),max:Math.max(...relief.elevation),center:relief.center,referenceOnly:true};scene.userData.landscapeStyle='authored-alpine-valley';scene.userData.mountainReferences=SWISS_PEAKS.map(p=>({id:p.id,name:p.name}));const rocks=[],pose=new T.Object3D();let seed=931;const noise=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<1700;i++){const x=(noise()-.5)*360,z=-64-noise()*195,y=height(x,z),slope=Math.hypot(height(x+1,z)-height(x-1,z),height(x,z+1)-height(x,z-1));if(y<11||y>83||slope<.5||slope>1.8)continue;const size=.3+noise()*1.3;pose.position.set(x,y+size*.04,z);pose.rotation.set(noise(),noise()*6,noise());pose.scale.set(size,size*.6,size*.85);pose.updateMatrix();rocks.push(pose.matrix.clone());}const scree=new T.InstancedMesh(new T.IcosahedronGeometry(1,1),rockMaterial,rocks.length);rocks.forEach((m,i)=>scree.setMatrixAt(i,m));scree.userData.kind='mountain-scree';scene.add(scree);scene.userData.screeRocks=rocks.length;}
// A photographed-style needle spray, drawn at high resolution and used on branching boughs.
