needle.color.set('#ffffff');needle.map=needleTexture(['#446c49','#577f53','#6b8f60','#355f40']);if(typeof window!=='undefined'){const bough=new T.TextureLoader().load('assets/portmann/fir-bough-v2.webp');bough.colorSpace=T.SRGBColorSpace;bough.anisotropy=4;needle.map=bough;needle.alphaTest=.54;}needle.userData.kind='photographic-fir-bough-v2';
