function tree(x,z,s=1,golden=false){if(options.treeHabitat&&!options.treeHabitat(x,z))return null;const boughs=golden?larchMatrices:branchMatrices,y=height(x,z),root=new T.Group(),variant=Math.floor(rnd()*3),variation=.78+rnd()*.4,lean=(rnd()-.5)*.06;root.position.set(x,y,z);root.userData.scale=s;root.userData.species=golden?'Lärche':['Weisstanne','Fichte','Bergfichte'][variant];root.userData.kind=golden?'alpine-larch':'alpine-fir';scene.add(root);treeSites.push({x,z,y,golden,scale:s});dummy.position.set(x,y+2.25*s,z);dummy.rotation.set(lean,rnd()*6,0);dummy.scale.setScalar(s);dummy.updateMatrix();trunkMatrices.push(dummy.matrix.clone());const layers=golden?11:13;for(let layer=0;layer<layers;layer++){const f=layer/(layers-1),baseY=.62+f*3.91,profile=Math.pow(1-f,variant===0?.57:variant===1?.86:.72),radius=(profile*(variant===0?1.9:1.55)+.06)*variation,count=golden?5:6+(layer%3);for(let j=0;j<count;j++){const a=j/count*Math.PI*2+layer*2.399+rnd()*.18,length=radius*(.84+rnd()*.28);dummy.position.set(x+lean*baseY*s,y+baseY*s,z);dummy.rotation.set((rnd()-.5)*.15,a,(variant===1?-.13:layer<4?-.02:.09)+(rnd()-.5)*.12);dummy.scale.set(length*s,1*s,length*(golden?.75:.86)*s);dummy.updateMatrix();boughs.push(dummy.matrix.clone());}}for(let i=0;i<4;i++){dummy.position.set(x+lean*4.45*s,y+4.45*s,z);dummy.rotation.set(0,i*Math.PI/2,-.95);dummy.scale.set(.4*s,.55*s,.28*s);dummy.updateMatrix();boughs.push(dummy.matrix.clone());}return root;}
