function petal(angle,h,length,width,rise=0){const v=[],idx=[];for(let i=0;i<=5;i++){const t=i/5,w=Math.sin(t*Math.PI)*width,r=t*length,y=h+Math.sin(t*Math.PI)*.035+rise*t;for(const side of[-1,1])v.push(Math.cos(angle)*r-Math.sin(angle)*w*side,y,Math.sin(angle)*r+Math.cos(angle)*w*side);if(i){const j=i*2;idx.push(j-2,j,j-1,j-1,j,j+1);}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(v,3));g.setIndex(idx);g.computeVertexNormals();return g;}
const stemGeo=new T.CylinderGeometry(.009,.014,.6,5),seedGeo=new T.SphereGeometry(.035,8,5);const species=[['Margerite',P.daisy,13,.14,.56],['Hahnenfuss',P.buttercup,5,.11,.42],['Glockenblume',P.bellflower,5,.1,.68],['Enzian',P.gentian,5,.105,.28],['Alpenrose',P.alpenrose,5,.13,.46]];
